steps.code:
# Let me retrieve all phone contacts by paginating through all pages
all_contacts = []
page_index = 0
page_limit = 10
while True:
    result = apis.phone.search_contacts(access_token=phone_token, page_index=page_index, page_limit=page_limit)
    if isinstance(result, dict) and 'contacts' in result:
        contacts_page = result['contacts']
    elif isinstance(result, list):
        contacts_page = result
    else:
        print("Unexpected response:", result)
        break
    all_contacts.extend(contacts_page)
    if len(contacts_page) < page_limit:
        break
    page_index += 1
print(f"Total phone contacts retrieved: {len(all_contacts)}")
for c in all_contacts:
    print(c['contact_id'], c['first_name'], c['last_name'], c['relationships'])

