# Let's verify the current state by fetching both lists again to ensure completeness.
# First, fetch all phone contacts with relationship 'friend' (paginate through all pages)
phone_friends = []
page_index = 0
while True:
    page = apis.phone.search_contacts(access_token=phone_login['access_token'], page_index=page_index, page_limit=20)
    contacts = page.get('contacts', [])
    if not contacts:
        break
    for contact in contacts:
        if 'friend' in contact.get('relationships', []):
            phone_friends.append(contact)
    page_index += 1
    if len(contacts) < 20:
        break

print(f"Phone friends count: {len(phone_friends)}")
for c in phone_friends:
    print(f"  {c['first_name']} {c['last_name']} - {c.get('email')}")

