# Let's search for each song and find the matching song_id by title and artists
# We'll need to handle pagination for search results

def find_song_id(title, artists):
    page_index = 0
    while True:
        result = apis.spotify.search_songs(access_token=spotify_token, query=title, page_index=page_index, page_limit=20)
        if not result or (isinstance(result, dict) and 'message' in result):
            return None
        for song in result:
            if song['title'].lower() == title.lower():
                # Check if all expected artists are present
                song_artist_names = [a['name'].lower() for a in song['artists']]
