steps.code:
# Get detailed info for each playlist to see their songs
playlist_details = {}
for pl in all_playlists:
    pl_id = pl['playlist_id']
    detail = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_token)
    playlist_details[pl_id] = detail
    print(f"Playlist {pl['title']} (ID={pl_id}): {len(detail.get('songs', []))} songs")
    for song in detail.get('songs', []):
        print(f"    Song ID={song['id']} Title={song['title']}")

