steps.code:
# Let's get all playlists from Spotify (checking all pages)
all_playlists = []
page_index = 0
while True:
    result = apis.spotify.show_playlist_library(access_token=spotify_token, page_index=page_index, page_limit=20)
    if isinstance(result, list):
        all_playlists.extend(result)
        if len(result) < 20:
            break
        page_index += 1
    else:
        print("Error or no more pages:", result)
        break

print(f"Total playlists found: {len(all_playlists)}")
for p in all_playlists:
    print(p)

