steps.code:
# Search for each song to archive and collect their song IDs
archive_song_ids = set()
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(access_token=login_result["access_token"], query=query, page_limit=20)
    # Find exact match
    found = None
    for r in results:
        if r["title"].lower() == song["title"].lower():
            # Check if any artist matches
            for artist in r["artists"]:
                if artist["name"].lower() == song["artist"].lower():
                    found = r
                    break
            if found:
                break
    if found:
        archive_song_ids.add(found["song_id"])
        print(f"Found: {song['title']} by {song['artist']} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal unique song IDs to archive: {len(archive_song_ids)}")
print(archive_song_ids)

