steps.code:
# Verify all archived songs have been removed from all playlists except "Old Songs" (654)
# Check each playlist's current songs
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
playlists_to_check = [p for p in all_playlists if p["playlist_id"] != 654]

all_clean = True
for playlist in playlists_to_check:
    playlist_detail = apis.spotify.show_playlist(playlist_id=playlist["playlist_id"], access_token=login_result["access_token"])
    current_song_ids = {song["id"] for song in playlist_detail["songs"]}
    remaining_archived = current_song_ids & archived_song_ids
    if remaining_archived:
        all_clean = False
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) still has archived songs: {remaining_archived}")
    else:
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) is clean")

if all_clean:
    print("All archived songs have been removed from all other playlists.")
else:
    print("Some archived songs remain. Need to remove them.")

