    result = apis.spotify.search_songs(query=query, access_token=spotify_token, page_limit=20)
    # Print only the first result that matches exactly
    for song in result:
        if song['title'].lower() == query.lower():
            print(f"{song['title']}: {song['release_date']}")
            break
    else:
        print(f"No exact match for {query}")

