steps.code:
# Parse the note content to extract songs and their release status
content = note_result['content']
lines = content.strip().split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        # Remove leading "- "
        line = line[2:]
        # Split by " BY " to get title and artist part
        if ' BY ' in line:
            title_part, artist_part = line.split(' BY ', 1)
            # Extract RELEASED_AT
            if ' RELEASED_AT ' in artist_part:
                artist_name, released = artist_part.split(' RELEASED_AT ', 1)
                songs.append({'title': title_part.strip(), 'artists': artist_name.strip(), 'released': released.strip()})
            else:
                songs.append({'title': title_part.strip(), 'artists': artist_part.strip(), 'released': None})
        else:
            # No BY? skip
            pass

# Print songs with TODO
for s in songs:
    if s['released'] == 'TODO':
        print(s)

