# Parse the note content to extract songs with TODO.
lines = note_content.split('\n')
songs_todo = []
for line in lines:
    if line.startswith('- '):
        # Format: - Song Title BY Artist1, Artist2 RELEASED_AT TODO
        # We need to extract title and artists.
        # Remove leading "- " and split on " BY " and then on " RELEASED_AT "
        line = line[2:]  # remove "- "
        if ' RELEASED_AT ' in line:
            song_part, release_part = line.split(' RELEASED_AT ', 1)
            if release_part == 'TODO':
                # song_part is "Song Title BY Artist1, Artist2"
                if ' BY ' in song_part:
                    title, artists = song_part.split(' BY ', 1)
                    songs_todo.append({'title': title, 'artists': artists})
                else:
                    # maybe no BY? but all have BY
                    songs_todo.append({'title': song_part, 'artists': ''})
print(songs_todo)

